import{_ as o,o as a,c as i,a5 as t}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Realtime In-App Notifications — plan","description":"","frontmatter":{},"headers":[],"relativePath":"feature/realtime-notifications/plan.md","filePath":"feature/realtime-notifications/plan.md"}'),c={name:"feature/realtime-notifications/plan.md"};function n(r,e,s,l,d,u){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="realtime-in-app-notifications-—-plan" tabindex="-1">Realtime In-App Notifications — plan <a class="header-anchor" href="#realtime-in-app-notifications-—-plan" aria-label="Permalink to &quot;Realtime In-App Notifications — plan&quot;">​</a></h1><h2 id="approach" tabindex="-1">Approach <a class="header-anchor" href="#approach" aria-label="Permalink to &quot;Approach&quot;">​</a></h2><p>Database-driven push. A Postgres trigger runs <code>pg_notify(&#39;user_notification&#39;, user_id)</code> on every insert into <code>user_notifications</code>. NOTIFY is delivered only on commit. One listener per business-service instance pushes <code>{&quot;type&quot;:&quot;NOTIFICATION&quot;}</code> to that user over STOMP.</p><p>Why not wrap each writer: there are about ten writers (raw SQL in chat, task outbox, billing, Admin broadcast, subscription lifecycle, …). The trigger covers all of them, and any future writer, with no code in the writer.</p><h2 id="database-brandhub-infrastructure" tabindex="-1">Database (brandhub-infrastructure) <a class="header-anchor" href="#database-brandhub-infrastructure" aria-label="Permalink to &quot;Database (brandhub-infrastructure)&quot;">​</a></h2><ul><li><code>docs/database/migrations/2026-11-21-user-notification-realtime.sql</code> — function + trigger (idempotent: <code>CREATE OR REPLACE</code>). Also appended to <code>init-postgres-v2.sql</code>.</li></ul><h2 id="business-service" tabindex="-1">business-service <a class="header-anchor" href="#business-service" aria-label="Permalink to &quot;business-service&quot;">​</a></h2><ul><li><code>service/NotificationRealtimeListener.java</code> — virtual thread, own JDBC connection (<code>DataSourceProperties</code>), <code>LISTEN</code>, <code>PGConnection.getNotifications(10s)</code>, <code>convertAndSendToUser(userId, &quot;/queue/notifications&quot;)</code>, reconnects every 5 s. Off switch: <code>app.notifications.realtime.enabled</code> (off in <code>application-test.yml</code>).</li><li><code>pom.xml</code> — postgresql driver scope <code>runtime</code> → compile (needed for <code>PGConnection</code>).</li><li><code>security/ChatInboundChannelInterceptor.java</code> — allow SUBSCRIBE <code>/user/queue/notifications</code>.</li><li><code>service/UserNotificationService.java</code> — single <code>notify(Notice)</code> write path; existing helpers delegate to it; new <code>publishSucceeded</code>.</li><li>Event writers: <ul><li><code>controller/InternalPostController.java</code> — notify author on status change to PUBLISHED / FAILED.</li><li><code>service/impl/TaskApprovalOutbox.java</code> + <code>TaskNotificationWorker.java</code> — <code>TASK_REVIEW_APPROVED</code>.</li><li><code>service/admin/ContentModerationService.java</code> — in-app decision.</li><li><code>service/AgencyBillingService.java</code> — Owner after fulfilment.</li><li><code>service/impl/WorkspaceServiceImpl.java</code> — invite / accept / remove / role change.</li><li><code>service/ContentRequestService.java</code>, <code>service/ContentRequestReviewService.java</code>.</li></ul></li></ul><h2 id="web" tabindex="-1">web <a class="header-anchor" href="#web" aria-label="Permalink to &quot;web&quot;">​</a></h2><ul><li><code>src/hooks/useNotificationSocket.ts</code> — STOMP on <code>/ws/chat</code> (same endpoint and JWT check as chat), subscribe <code>/user/queue/notifications</code>, catch-up refetch on (re)connect.</li><li><code>src/components/layout/Navbar.tsx</code> — refetch on signal, toast new unread items, polling 30 s → 120 s fallback.</li><li><code>src/i18n/locales/vi/notifications.json</code>, <code>src/i18n/locales/en/notifications.json</code> — <code>open</code>.</li></ul><h2 id="gateway" tabindex="-1">Gateway <a class="header-anchor" href="#gateway" aria-label="Permalink to &quot;Gateway&quot;">​</a></h2><p>No change: <code>/ws/chat</code> is already routed.</p><h2 id="deploy-order" tabindex="-1">Deploy order <a class="header-anchor" href="#deploy-order" aria-label="Permalink to &quot;Deploy order&quot;">​</a></h2><ol><li>Run the migration on Postgres (without it nothing breaks; only realtime stays off).</li><li>Deploy business-service, then web.</li></ol>',14)])])}const f=o(c,[["render",n]]);export{h as __pageData,f as default};
